#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/stale_pid_recovery_v21_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/runtime_control.py "$BK/" 2>/dev/null || true
cp -a scripts/companyosctl "$BK/" 2>/dev/null || true

echo "" | base64 -d > "$PREFIX/tmp/companyos_stale_pid_patch_v21.py"
python "$PREFIX/tmp/companyos_stale_pid_patch_v21.py"
rm -f "$PREFIX/tmp/companyos_stale_pid_patch_v21.py"

echo "" | base64 -d > tests/test_runtime_control_stale_pid_recovery_v21.py
echo "" | base64 -d > scripts/companyos_recover_supervisor
chmod +x scripts/companyos_recover_supervisor

echo "[1/6] Compile"
python -m py_compile companyos/runtime/runtime_control.py tests/test_runtime_control_stale_pid_recovery_v21.py

echo "[2/6] Unit tests"
python -m unittest tests.test_runtime_control_stale_pid_recovery_v21 -v

echo "[3/6] Recovery run"
scripts/companyos_recover_supervisor | tee .companyos_runtime/stale_pid_recovery_v21.log

echo "[4/6] Verify supervisor process"
python - <<'PY'
import json, os
from pathlib import Path
p = Path(".companyos_runtime/service_supervisor_state.json")
d = json.loads(p.read_text()) if p.exists() else {}
pid = d.get("supervisor_pid")
alive = False
if pid:
    try:
        os.kill(int(pid), 0)
        alive = True
    except Exception:
        alive = False
print("SUPERVISOR_PID=", pid)
print("SUPERVISOR_ALIVE=", alive)
print("STOP_REQUESTED=", d.get("stop_requested"))
if not alive:
    raise SystemExit("ERROR: supervisor did not recover")
PY

echo "[5/6] Commit/push"
git add companyos/runtime/runtime_control.py scripts/companyos_recover_supervisor tests/test_runtime_control_stale_pid_recovery_v21.py
git diff --cached --quiet || git commit -m "Repair stale supervisor PID recovery and startup"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[6/6] Final health"
scripts/companyosctl status || true
scripts/companyosctl health || true

echo "BACKUP=$BK"
echo "COMPANYOS_STALE_PID_SUPERVISOR_RECOVERY_V21=PASS"
